/**
 * Custom Cloudflare Worker entry.
 *
 * OpenNext generates `.open-next/worker.js` at build time. This wrapper
 * re-uses its fetch handler and adds the pieces only a custom entry can
 * expose: the OrderFeed Durable Object and the WebSocket upgrade path.
 *
 * WebSocket upgrades are intercepted BEFORE Next.js: route handlers cannot
 * reliably pass a 101 response through the framework layer.
 */

// Generated by `opennextjs-cloudflare build`; typed by the stub created in
// scripts/ensure-opennext-stub.mjs so tsc/next build work on a clean clone.
import handler from "./.open-next/worker.js";
import { OrderFeed } from "./durable-objects/order-feed";
import { withDbRequest } from "./lib/db/request-context";

export { OrderFeed };

// The cache stack's Durable Objects are exported by the generated worker.
export {
  DOQueueHandler,
  DOShardedTagCache,
  BucketCachePurge,
} from "./.open-next/worker.js";

export default {
  async fetch(
    request: Request,
    env: CloudflareEnv,
    ctx: ExecutionContext,
  ): Promise<Response> {
    const url = new URL(request.url);
    if (
      url.pathname === "/api/realtime" &&
      request.headers.get("Upgrade") === "websocket"
    ) {
      const stub = env.ORDER_FEED.get(env.ORDER_FEED.idFromName("jpasta"));
      return stub.fetch(request);
    }
    // A fresh DB client per request: a pooled Postgres socket cannot cross
    // request boundaries on Workers (see lib/db/request-context.ts).
    return withDbRequest(() => handler.fetch(request, env, ctx));
  },

  // Daily housekeeping via the Cron Trigger in wrangler.jsonc. Calling our
  // own route keeps the DB code in the Next runtime (Hyperdrive pool) rather
  // than opening a second pool from the Worker entry.
  async scheduled(
    _event: ScheduledController,
    env: CloudflareEnv,
    ctx: ExecutionContext,
  ): Promise<void> {
    const secret = (env as CloudflareEnv & { CRON_SECRET?: string })
      .CRON_SECRET;
    if (!secret) return;
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch("https://jpasta/api/cron/prune", {
        headers: { authorization: `Bearer ${secret}` },
      }).catch(() => undefined),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;
